SELECT
    DATE(r.answered_at)                                   AS stat_date,
    COUNT(*)                                              AS answered_count,
    SUM(CASE WHEN r.is_correct = 1 THEN 1 ELSE 0 END)     AS correct_count,
    SUM(LEAST(r.duration_ms, 600000)) DIV 1000            AS duration_sec
FROM user_answer_record r
WHERE r.user_id = #{userId}
  AND r.subject_id = #{subjectId}
  AND r.is_correct IS NOT NULL
  AND r.answered_at >= #{sinceDate}
GROUP BY DATE(r.answered_at)
ORDER BY stat_date
LIMIT #{limit}

SELECT stat_date
FROM stat_daily
WHERE user_id = #{userId}
  AND answered_count > 0
ORDER BY stat_date DESC
LIMIT #{limit}

SELECT
    kp.id             AS kp_id,
    kp.name           AS kp_name,
    s.answered_count  AS answered_count,
    s.accuracy        AS accuracy,
    s.mastery         AS mastery
FROM stat_user_kp s
JOIN rk_knowledge_point kp ON kp.id = s.kp_id
WHERE s.user_id = #{userId}
  AND s.subject_id = #{subjectId}
  AND s.mastery < #{maxMastery}
ORDER BY s.mastery ASC, s.kp_id ASC
LIMIT #{limit}
